import clsx from 'clsx';
import React, { useMemo } from 'react';
import type {
  GroupBase,
  ControlProps as ReactSelectControlProps,
} from 'react-select';

import { ChevronDownSmallIcon } from '@dynatrace/strato-icons';

import { HiddenSelectV2 } from './HiddenSelect.js';
import { _isValueContainerComponent } from './ValueContainer.js';
import { Button } from '../../../buttons/button/Button.js';
import { SharedInputPropsContext } from '../../../core/contexts/SharedInputPropsContext.js';
import { _useFormControlState } from '../../../core/hooks/useFormControlState.js';
import { _useId } from '../../../core/hooks/useId.js';
import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import { OverlayStackingProvider } from '../../../core/providers/OverlayStackingProvider.js';
import { useFocusRing } from '../../../core/styles/useFocusRing.js';
import { mergeProps as _mergeProps } from '../../../core/utils/merge-props.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Hint } from '../../forms-core/components/hint/Hint.js';
import { _useFormFieldContext } from '../../forms-core/hooks/useFormFieldContext.js';
import { useSelectMenuContext } from '../hooks/use-select-menu-context.js';
import { SelectActions } from '../state/select-menu-state-reducer.js';
import {
  selectTriggerCSS,
  selectTriggerIconWrapperCSS,
} from '../styles/Select.sty.js';

//#region Typings
type ControlProps<
  OptionValue,
  isMulti extends boolean,
  Group extends GroupBase<OptionValue>,
> = ReactSelectControlProps<OptionValue, isMulti, Group>;
//#endregion Typings

/** Iterates over child nodes to extract the value container. */
function getSelectValueContainer<
  OptionValue,
  isMulti extends boolean,
  Group extends GroupBase<OptionValue>,
>(children: React.ReactNode) {
  let container;

  React.Children.forEach(children, (child) => {
    if (_isValueContainerComponent<OptionValue, isMulti, Group>(child)) {
      container = child;
    }
  });

  return container;
}

export function Control<
  OptionValue,
  isMulti extends boolean,
  Group extends GroupBase<OptionValue>,
>(props: ControlProps<OptionValue, isMulti, Group>) {
  const { children, isDisabled, innerRef, innerProps, selectProps } = props;
  const { 'aria-labelledby': ariaLabelledBy, ...ariaLabelingProps } =
    selectProps.ariaLabelingProps ?? {};
  const {
    className: consumerClassName,
    style: consumerStyle,
    // The select testing helpers use the trigger test id for various actions, keeping the default for now.
    'data-testid': dataTestId = 'selectv2-trigger',
  } = selectProps.componentProps.trigger ?? {};

  const rootRef = useMergeRefs<HTMLElement>([
    innerRef,
    selectProps.setTriggerRef,
  ]);

  const valueContainer = getSelectValueContainer(children);
  const { controlId } = _useFormFieldContext();

  const triggerId = _useId({ prefix: 'strato-select-trigger' });
  const selectInputId = selectProps['selectInputId'] || controlId;
  const customTriggerId = selectProps.customTrigger?.props.id;

  const hiddenReactSelectInput = valueContainer?.props.children?.[1];
  const hiddenInput = useMemo(
    () =>
      React.cloneElement(hiddenReactSelectInput, {
        ...hiddenReactSelectInput.props,
        key: 'hidden-react-select-input',
        id: selectInputId,
        'aria-labelledby': ariaLabelledBy ?? customTriggerId ?? triggerId,
        ...ariaLabelingProps,
      }),
    [
      hiddenReactSelectInput,
      selectInputId,
      ariaLabelingProps,
      triggerId,
      ariaLabelledBy,
      customTriggerId,
    ],
  );

  const [hasError, hint] = _useFormControlState(selectProps.controlState);

  const { focusProps, focusClassName } = useFocusRing({
    variant: hasError ? 'critical' : 'neutral',
    focusWithin: true,
  });

  const { dispatch } = useSelectMenuContext();

  const interactionProps = useMemo(() => {
    return {
      onTouchStart: () => {
        dispatch({
          type: SelectActions.SELECTFOCUS,
        });
      },
      onClick: () => {
        dispatch({
          type: SelectActions.SELECTFOCUS,
        });
      },
      onKeyDown: (event) => {
        if (
          (event.key === 'Enter' || event.key === ' ') &&
          !selectProps.isMulti
        ) {
          dispatch({
            type: SelectActions.CLOSE,
          });
        }
      },
    };
  }, [dispatch, selectProps.isMulti]);

  const customTrigger = useMemo(() => {
    if (selectProps.customTrigger) {
      /** React Select dummyInput is applied in the ValueContainers children in order to
       * handle / react to the inputs correctly. This one needs to be passed through in order for the
       * trigger to work correctly.
       */

      return React.cloneElement(
        selectProps.customTrigger,
        {
          key: 'custom-trigger',
          ref: rootRef,
          id: triggerId,
          ..._mergeProps(
            selectProps.customTrigger.props,
            innerProps,
            interactionProps,
          ),
        },
        [selectProps.customTrigger.props.children, hiddenInput],
      );
    }
  }, [
    hiddenInput,
    innerProps,
    interactionProps,
    rootRef,
    selectProps.customTrigger,
    triggerId,
  ]);

  if (customTrigger) {
    return <OverlayStackingProvider>{customTrigger}</OverlayStackingProvider>;
  }

  return (
    <Flex padding={0} flexDirection="column" gap={4}>
      <SharedInputPropsContext.Provider value={{}}>
        <OverlayStackingProvider>
          <Button
            ref={rootRef}
            id={triggerId}
            textAlign="start"
            data-testid={dataTestId}
            disabled={isDisabled}
            width={selectProps.triggerWidth}
            {...innerProps}
            variant="emphasized"
            {...interactionProps}
            color={hasError ? 'critical' : 'neutral'}
            className={clsx(
              'strato-components-selectv2-control-trigger',
              selectTriggerCSS({
                fullWidth:
                  selectProps.triggerWidth === 'full' ||
                  selectProps.triggerWidth === '100%',
              }),
              focusClassName,
              consumerClassName,
            )}
            style={consumerStyle}
            as="div"
            {...focusProps}
          >
            {selectProps.prefix && (
              <Button.Prefix
                data-testid={selectProps.prefix.props['data-testid']}
                className={selectProps.prefix.props.className}
                style={selectProps.prefix.props.style}
              >
                {selectProps.prefix.props.children}
              </Button.Prefix>
            )}
            <Button.Label>
              {hiddenInput}
              {valueContainer}
            </Button.Label>
            <Button.Suffix>
              <div
                className={clsx(
                  selectTriggerIconWrapperCSS({
                    isOverlayOpen: selectProps.menuIsOpen,
                  }),
                )}
              >
                <ChevronDownSmallIcon />
              </div>
            </Button.Suffix>
          </Button>
        </OverlayStackingProvider>
      </SharedInputPropsContext.Provider>
      <HiddenSelectV2<OptionValue>
        ref={selectProps.hiddenSelectRef}
        required={selectProps.isRequired}
        selectedValues={selectProps.value}
        name={selectProps.hiddenSelectName}
      />
      <Hint hasError={hasError} disabled={isDisabled}>
        {hint}
      </Hint>
    </Flex>
  );
}
